FILES = {'apps/explorer/src/services/boss/lifecycle.ts': 'export const SYNAPSE_BOSS_SERVICES_PROVENANCE = {\n  repository: "snissn/synapse-sdk",\n  branch: "gpt56/tracker-filecoin-boss-sdk",\n  commit: "f35aeeb822bb9f95d03a66a51e85ed5f1fdcca02",\n} as const;\n\nexport const BOSS_LIFECYCLE_REVIEW_MAX_AGE_MS = 5 * 60 * 1_000;\n\nconst ADDRESS = /^0x[0-9a-fA-F]{40}$/;\nconst BYTES32 = /^0x[0-9a-fA-F]{64}$/;\nconst DECIMAL = /^(0|[1-9]\\d*)$/;\nconst TRANSACTION_HASH = /^0x[0-9a-fA-F]{64}$/;\nconst ACTIONS = new Set<BossLifecycleAction>(["sync", "top-up", "pause", "resume", "stop"]);\nconst STAGES = new Set<BossServicesStage>([\n  "deposit",\n  "approve-operator",\n  "deploy-account",\n  "accept-offer",\n  "top-up-fixed-budget",\n  "acknowledge-activation",\n  "activate",\n  "sync",\n  "claim",\n  "top-up",\n  "pause",\n  "resume",\n  "stop",\n  "settle",\n]);\n\nexport type BossLifecycleAction = "sync" | "top-up" | "pause" | "resume" | "stop";\nexport type BossServicesStage =\n  | "deposit"\n  | "approve-operator"\n  | "deploy-account"\n  | "accept-offer"\n  | "top-up-fixed-budget"\n  | "acknowledge-activation"\n  | "activate"\n  | "sync"\n  | "claim"\n  | "top-up"\n  | "pause"\n  | "resume"\n  | "stop"\n  | "settle";\n\nexport type BossLifecycleErrorCode = "INVALID_REVIEW" | "STALE_REVIEW" | "SDK_UNAVAILABLE";\n\nexport class BossLifecycleError extends Error {\n  constructor(\n    readonly code: BossLifecycleErrorCode,\n    message: string,\n    readonly details: readonly string[] = [],\n  ) {\n    super(message);\n    this.name = "BossLifecycleError";\n  }\n}\n\nexport interface BossLifecycleReference {\n  account: string;\n  subscriptionId: string;\n}\n\nexport interface BossServicesTransactionEvidenceLike {\n  stage: BossServicesStage;\n  hash: string;\n  receipt: unknown;\n}\n\nexport interface BossServicesManagerLike {\n  get(input: BossLifecycleReference): Promise<unknown>;\n  reconcile(input: BossLifecycleReference): Promise<unknown>;\n  sync(input: BossLifecycleReference): Promise<BossServicesTransactionEvidenceLike>;\n  topUp(input: BossLifecycleReference & { newFixedBudget: bigint }): Promise<BossServicesTransactionEvidenceLike>;\n  pause(input: BossLifecycleReference): Promise<BossServicesTransactionEvidenceLike>;\n  resume(input: BossLifecycleReference): Promise<BossServicesTransactionEvidenceLike>;\n  stop(input: BossLifecycleReference): Promise<BossServicesTransactionEvidenceLike>;\n}\n\nexport type BossServicesResolution =\n  | { status: "available"; manager: BossServicesManagerLike }\n  | { status: "unavailable"; reason: string };\n\nconst REQUIRED_MANAGER_METHODS = ["get", "reconcile", "sync", "topUp", "pause", "resume", "stop"] as const;\n\nexport function resolveBossServicesManager(synapse: unknown): BossServicesResolution {\n  if (!isRecord(synapse) || !isRecord(synapse.services)) {\n    return {\n      status: "unavailable",\n      reason:\n        "The connected @filoz/synapse-sdk package does not expose Synapse.services. The Boss tracker API is not yet present in the published Explorer dependency.",\n    };\n  }\n\n  const services = synapse.services;\n  const missing = REQUIRED_MANAGER_METHODS.filter((method) => typeof services[method] !== "function");\n  if (missing.length > 0) {\n    return {\n      status: "unavailable",\n      reason: `Synapse.services is missing required maintained lifecycle methods: ${missing.join(", ")}.`,\n    };\n  }\n\n  return { status: "available", manager: services as unknown as BossServicesManagerLike };\n}\n\nexport interface PrepareBossLifecycleReviewInput {\n  action: BossLifecycleAction;\n  chainId: number;\n  wallet: string;\n  account: string;\n  subscriptionId: string;\n  railId: string;\n  newFixedBudget?: bigint;\n  createdAtMs: number;\n}\n\nexport interface BossLifecycleReview {\n  readonly schemaVersion: 1;\n  readonly action: BossLifecycleAction;\n  readonly chainId: number;\n  readonly wallet: string;\n  readonly account: string;\n  readonly subscriptionId: string;\n  readonly railId: string;\n  readonly newFixedBudget?: bigint;\n  readonly createdAtMs: number;\n  readonly reviewKey: string;\n}\n\nexport interface BossLifecycleCurrentContext {\n  chainId: number | undefined;\n  wallet: string | undefined;\n  account: string;\n  subscriptionId: string;\n  railId: string;\n  nowMs?: number;\n}\n\nexport interface BossLifecycleReviewMismatch {\n  field: "chainId" | "wallet" | "account" | "subscriptionId" | "railId";\n  reviewed: string;\n  current: string;\n}\n\nexport function prepareBossLifecycleReview(input: PrepareBossLifecycleReviewInput): BossLifecycleReview {\n  return Object.freeze(buildReview(input));\n}\n\nexport function compareBossLifecycleReview(\n  review: BossLifecycleReview,\n  current: BossLifecycleCurrentContext,\n): BossLifecycleReviewMismatch[] {\n  const mismatches: BossLifecycleReviewMismatch[] = [];\n  compare("chainId", review.chainId.toString(), current.chainId?.toString() ?? "disconnected", mismatches);\n  compare("wallet", review.wallet, normalizeOptionalAddress(current.wallet), mismatches);\n  compare("account", review.account, normalizeOptionalAddress(current.account), mismatches);\n  compare("subscriptionId", review.subscriptionId, normalizeOptionalBytes32(current.subscriptionId), mismatches);\n  compare("railId", review.railId, normalizeOptionalDecimal(current.railId), mismatches);\n  return mismatches;\n}\n\nexport interface BossLifecycleTransactionEvidence {\n  stage: BossServicesStage;\n  txHash: string;\n  receiptStatus?: string;\n  blockNumber?: string;\n}\n\nexport interface BossLifecycleManagerResult {\n  transactions: readonly BossLifecycleTransactionEvidence[];\n  failedStage?: BossServicesStage;\n}\n\nexport interface BossLifecycleReconciliation {\n  status: "succeeded" | "failed";\n  value?: unknown;\n  error?: string;\n}\n\nexport interface BossLifecycleExecutionReceipt {\n  review: BossLifecycleReview;\n  status: "succeeded" | "partial" | "failed";\n  result?: BossLifecycleManagerResult;\n  error?: string;\n  reconciliation: BossLifecycleReconciliation;\n}\n\nexport async function executeBossLifecycleReview(\n  manager: BossServicesManagerLike,\n  review: BossLifecycleReview,\n  current: BossLifecycleCurrentContext,\n): Promise<BossLifecycleExecutionReceipt> {\n  validateReviewIntegrity(review, current.nowMs ?? Date.now());\n\n  const mismatches = compareBossLifecycleReview(review, current);\n  if (mismatches.length > 0) {\n    throw new BossLifecycleError(\n      "STALE_REVIEW",\n      "Wallet, chain, account, subscription, or rail changed after review",\n      mismatches.map((mismatch) => `${mismatch.field}: reviewed=${mismatch.reviewed}, current=${mismatch.current}`),\n    );\n  }\n\n  const reference = { account: review.account, subscriptionId: review.subscriptionId };\n  let result: BossLifecycleManagerResult | undefined;\n  let status: BossLifecycleExecutionReceipt["status"] = "succeeded";\n  let executionError: string | undefined;\n\n  try {\n    let transaction: BossServicesTransactionEvidenceLike;\n    switch (review.action) {\n      case "sync":\n        transaction = await manager.sync(reference);\n        break;\n      case "top-up":\n        transaction = await manager.topUp({\n          ...reference,\n          newFixedBudget: review.newFixedBudget as bigint,\n        });\n        break;\n      case "pause":\n        transaction = await manager.pause(reference);\n        break;\n      case "resume":\n        transaction = await manager.resume(reference);\n        break;\n      case "stop":\n        transaction = await manager.stop(reference);\n        break;\n    }\n    result = { transactions: [normalizeTransaction(transaction)] };\n  } catch (error) {\n    if (isPartialCompletion(error)) {\n      try {\n        const transactions = error.completed.map(normalizeTransaction);\n        status = transactions.length > 0 ? "partial" : "failed";\n        result = {\n          transactions,\n          failedStage: normalizeStage(error.failedStage, "failed stage"),\n        };\n        executionError = errorMessage(error);\n      } catch (evidenceError) {\n        status = "failed";\n        executionError = `${errorMessage(error)} Invalid completed transaction evidence: ${errorMessage(evidenceError)}`;\n      }\n    } else {\n      status = "failed";\n      executionError = errorMessage(error);\n    }\n  }\n\n  const reconciliation = await reconcileAfterExecution(manager, reference);\n  return {\n    review,\n    status,\n    result,\n    error: executionError,\n    reconciliation,\n  };\n}\n\nexport function serializeBossLifecycleEvidence(value: unknown): string {\n  return (\n    JSON.stringify(value, (_key, nested) => (typeof nested === "bigint" ? nested.toString() : nested), 2) ?? "null"\n  );\n}\n\nfunction buildReview(input: PrepareBossLifecycleReviewInput): BossLifecycleReview {\n  if (!ACTIONS.has(input.action)) {\n    throw new BossLifecycleError("INVALID_REVIEW", "Unsupported Boss lifecycle action");\n  }\n  if (!Number.isSafeInteger(input.chainId) || input.chainId <= 0) {\n    throw new BossLifecycleError("INVALID_REVIEW", "Chain ID must be a positive safe integer");\n  }\n  if (!Number.isSafeInteger(input.createdAtMs) || input.createdAtMs < 0) {\n    throw new BossLifecycleError("INVALID_REVIEW", "Review timestamp must be a non-negative safe integer");\n  }\n\n  const wallet = normalizeAddress(input.wallet, "Wallet");\n  const account = normalizeAddress(input.account, "Boss account");\n  const subscriptionId = normalizeBytes32(input.subscriptionId, "Subscription ID");\n  const railId = normalizeDecimal(input.railId, "Rail ID");\n\n  if (input.action === "top-up") {\n    if (input.newFixedBudget === undefined || input.newFixedBudget <= 0n) {\n      throw new BossLifecycleError(\n        "INVALID_REVIEW",\n        "Top-up requires an explicit positive absolute fixed-budget target in token base units",\n      );\n    }\n  } else if (input.newFixedBudget !== undefined) {\n    throw new BossLifecycleError("INVALID_REVIEW", `${input.action} must not carry a fixed-budget target`);\n  }\n\n  const reviewKey = [\n    "boss-lifecycle-review-v1",\n    input.action,\n    input.chainId.toString(),\n    wallet,\n    account,\n    subscriptionId,\n    railId,\n    input.newFixedBudget?.toString() ?? "none",\n    input.createdAtMs.toString(),\n  ].join(":");\n\n  return {\n    schemaVersion: 1,\n    action: input.action,\n    chainId: input.chainId,\n    wallet,\n    account,\n    subscriptionId,\n    railId,\n    newFixedBudget: input.newFixedBudget,\n    createdAtMs: input.createdAtMs,\n    reviewKey,\n  };\n}\n\nfunction validateReviewIntegrity(review: BossLifecycleReview, nowMs: number): void {\n  if (!isRecord(review) || review.schemaVersion !== 1) {\n    throw new BossLifecycleError("INVALID_REVIEW", "Unsupported Boss lifecycle review schema");\n  }\n  if (!Number.isSafeInteger(nowMs) || nowMs < 0) {\n    throw new BossLifecycleError("INVALID_REVIEW", "Current review-validation timestamp is invalid");\n  }\n\n  const rebuilt = buildReview({\n    action: review.action,\n    chainId: review.chainId,\n    wallet: review.wallet,\n    account: review.account,\n    subscriptionId: review.subscriptionId,\n    railId: review.railId,\n    newFixedBudget: review.newFixedBudget,\n    createdAtMs: review.createdAtMs,\n  });\n  if (review.reviewKey !== rebuilt.reviewKey) {\n    throw new BossLifecycleError(\n      "INVALID_REVIEW",\n      "The review payload changed after confirmation",\n      [`expected=${rebuilt.reviewKey}`, `received=${review.reviewKey}`],\n    );\n  }\n\n  const age = nowMs - review.createdAtMs;\n  if (age < 0 || age > BOSS_LIFECYCLE_REVIEW_MAX_AGE_MS) {\n    throw new BossLifecycleError(\n      "STALE_REVIEW",\n      "The lifecycle review expired; prepare a fresh review before submitting",\n      [`ageMs=${age}`, `maximumAgeMs=${BOSS_LIFECYCLE_REVIEW_MAX_AGE_MS}`],\n    );\n  }\n}\n\nasync function reconcileAfterExecution(\n  manager: BossServicesManagerLike,\n  reference: BossLifecycleReference,\n): Promise<BossLifecycleReconciliation> {\n  try {\n    return { status: "succeeded", value: await manager.reconcile(reference) };\n  } catch (error) {\n    return { status: "failed", error: errorMessage(error) };\n  }\n}\n\nfunction normalizeTransaction(value: BossServicesTransactionEvidenceLike): BossLifecycleTransactionEvidence {\n  if (!isRecord(value)) {\n    throw new Error("Synapse.services returned malformed transaction evidence");\n  }\n  const stage = normalizeStage(value.stage, "transaction stage");\n  if (typeof value.hash !== "string" || !TRANSACTION_HASH.test(value.hash)) {\n    throw new Error("Synapse.services returned an invalid transaction hash");\n  }\n\n  const evidence: BossLifecycleTransactionEvidence = {\n    stage,\n    txHash: value.hash.toLowerCase(),\n  };\n  if (isRecord(value.receipt)) {\n    const status = scalarString(value.receipt.status);\n    const blockNumber = scalarString(value.receipt.blockNumber);\n    if (status !== undefined) evidence.receiptStatus = status;\n    if (blockNumber !== undefined) evidence.blockNumber = blockNumber;\n  }\n  return evidence;\n}\n\nfunction normalizeStage(value: unknown, label: string): BossServicesStage {\n  if (typeof value !== "string" || !STAGES.has(value as BossServicesStage)) {\n    throw new Error(`Synapse.services returned an invalid ${label}`);\n  }\n  return value as BossServicesStage;\n}\n\nfunction isPartialCompletion(\n  value: unknown,\n): value is Error & {\n  readonly failedStage: BossServicesStage;\n  readonly completed: readonly BossServicesTransactionEvidenceLike[];\n} {\n  return (\n    value instanceof Error &&\n    value.name === "BossServicesPartialCompletionError" &&\n    isRecord(value) &&\n    Array.isArray(value.completed) &&\n    typeof value.failedStage === "string"\n  );\n}\n\nfunction scalarString(value: unknown): string | undefined {\n  if (typeof value === "bigint") return value.toString();\n  if (typeof value === "number" && Number.isSafeInteger(value)) return value.toString();\n  if (typeof value === "string" && DECIMAL.test(value)) return value;\n  return undefined;\n}\n\nfunction compare(\n  field: BossLifecycleReviewMismatch["field"],\n  reviewed: string,\n  current: string,\n  mismatches: BossLifecycleReviewMismatch[],\n): void {\n  if (reviewed !== current) mismatches.push({ field, reviewed, current });\n}\n\nfunction normalizeAddress(value: string, label: string): string {\n  if (!ADDRESS.test(value)) {\n    throw new BossLifecycleError("INVALID_REVIEW", `${label} is not a valid EVM address`);\n  }\n  return value.toLowerCase();\n}\n\nfunction normalizeBytes32(value: string, label: string): string {\n  if (!BYTES32.test(value)) {\n    throw new BossLifecycleError("INVALID_REVIEW", `${label} is not a valid bytes32 value`);\n  }\n  return value.toLowerCase();\n}\n\nfunction normalizeDecimal(value: string, label: string): string {\n  if (!DECIMAL.test(value)) {\n    throw new BossLifecycleError("INVALID_REVIEW", `${label} is not a canonical non-negative decimal integer`);\n  }\n  return value;\n}\n\nfunction normalizeOptionalAddress(value: string | undefined): string {\n  return value !== undefined && ADDRESS.test(value) ? value.toLowerCase() : (value ?? "disconnected");\n}\n\nfunction normalizeOptionalBytes32(value: string): string {\n  return BYTES32.test(value) ? value.toLowerCase() : value;\n}\n\nfunction normalizeOptionalDecimal(value: string): string {\n  return DECIMAL.test(value) ? value : value;\n}\n\nfunction errorMessage(error: unknown): string {\n  return error instanceof Error ? error.message : String(error);\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === "object" && value !== null;\n}\n', 'apps/explorer/src/services/boss/lifecycle.test.ts': 'import { describe, expect, it, vi } from "vitest";\nimport {\n  BOSS_LIFECYCLE_REVIEW_MAX_AGE_MS,\n  BossLifecycleError,\n  type BossLifecycleCurrentContext,\n  type BossLifecycleReview,\n  type BossServicesManagerLike,\n  type BossServicesStage,\n  compareBossLifecycleReview,\n  executeBossLifecycleReview,\n  prepareBossLifecycleReview,\n  resolveBossServicesManager,\n  serializeBossLifecycleEvidence,\n} from "./lifecycle";\n\nconst ADDRESS = (digit: string) => `0x${digit.repeat(40)}`;\nconst HASH = (digit: string) => `0x${digit.repeat(64)}`;\nconst CREATED_AT = 1_000_000;\n\nfunction transaction(stage: BossServicesStage, digit: string) {\n  return {\n    stage,\n    hash: HASH(digit),\n    receipt: {\n      status: 1n,\n      blockNumber: 123n,\n    },\n  };\n}\n\nfunction manager(overrides: Partial<BossServicesManagerLike> = {}): BossServicesManagerLike {\n  return {\n    get: vi.fn(async () => ({ state: "ACTIVE" })),\n    reconcile: vi.fn(async () => ({ boss: { state: "ACTIVE" }, pay: { railId: 42n } })),\n    sync: vi.fn(async () => transaction("sync", "1")),\n    topUp: vi.fn(async () => transaction("top-up", "2")),\n    pause: vi.fn(async () => transaction("pause", "3")),\n    resume: vi.fn(async () => transaction("resume", "4")),\n    stop: vi.fn(async () => transaction("stop", "5")),\n    ...overrides,\n  };\n}\n\nfunction review(overrides: Partial<Parameters<typeof prepareBossLifecycleReview>[0]> = {}): BossLifecycleReview {\n  return prepareBossLifecycleReview({\n    action: "sync",\n    chainId: 314159,\n    wallet: ADDRESS("1"),\n    account: ADDRESS("2"),\n    subscriptionId: HASH("3"),\n    railId: "42",\n    createdAtMs: CREATED_AT,\n    ...overrides,\n  });\n}\n\nfunction context(overrides: Partial<BossLifecycleCurrentContext> = {}): BossLifecycleCurrentContext {\n  return {\n    chainId: 314159,\n    wallet: ADDRESS("1"),\n    account: ADDRESS("2"),\n    subscriptionId: HASH("3"),\n    railId: "42",\n    nowMs: CREATED_AT + 1_000,\n    ...overrides,\n  };\n}\n\ndescribe("Boss lifecycle review", () => {\n  it("creates one normalized immutable review", () => {\n    const prepared = review({\n      action: "top-up",\n      wallet: ADDRESS("A"),\n      account: ADDRESS("B"),\n      subscriptionId: HASH("C"),\n      newFixedBudget: 500n,\n    });\n\n    expect(Object.isFrozen(prepared)).toBe(true);\n    expect(prepared).toMatchObject({\n      action: "top-up",\n      wallet: ADDRESS("a"),\n      account: ADDRESS("b"),\n      subscriptionId: HASH("c"),\n      newFixedBudget: 500n,\n    });\n    expect(prepared.reviewKey).toContain(":500:");\n  });\n\n  it("requires an absolute positive fixed-budget target only for top-up", () => {\n    expect(() => review({ action: "top-up" })).toThrow(/absolute fixed-budget target/i);\n    expect(() => review({ action: "top-up", newFixedBudget: 0n })).toThrow(/absolute fixed-budget target/i);\n    expect(() => review({ action: "pause", newFixedBudget: 1n })).toThrow(/must not carry/i);\n  });\n\n  it("reports every changed authority field", () => {\n    const mismatches = compareBossLifecycleReview(\n      review(),\n      context({\n        chainId: 314,\n        wallet: ADDRESS("9"),\n        account: ADDRESS("8"),\n        subscriptionId: HASH("7"),\n        railId: "43",\n      }),\n    );\n    expect(mismatches.map((mismatch) => mismatch.field)).toEqual([\n      "chainId",\n      "wallet",\n      "account",\n      "subscriptionId",\n      "railId",\n    ]);\n  });\n\n  it("executes exactly one SDK call, retains exact transaction evidence, and reconciles once", async () => {\n    const services = manager();\n    const receipt = await executeBossLifecycleReview(services, review(), context());\n\n    expect(services.sync).toHaveBeenCalledTimes(1);\n    expect(services.sync).toHaveBeenCalledWith({\n      account: ADDRESS("2"),\n      subscriptionId: HASH("3"),\n    });\n    expect(services.reconcile).toHaveBeenCalledTimes(1);\n    expect(receipt).toMatchObject({\n      status: "succeeded",\n      result: {\n        transactions: [\n          {\n            stage: "sync",\n            txHash: HASH("1"),\n            receiptStatus: "1",\n            blockNumber: "123",\n          },\n        ],\n      },\n      reconciliation: { status: "succeeded" },\n    });\n  });\n\n  it("passes the exact absolute newFixedBudget shape to Synapse.services.topUp", async () => {\n    const services = manager();\n    const prepared = review({ action: "top-up", newFixedBudget: 700n });\n\n    const receipt = await executeBossLifecycleReview(services, prepared, context());\n\n    expect(services.topUp).toHaveBeenCalledTimes(1);\n    expect(services.topUp).toHaveBeenCalledWith({\n      account: ADDRESS("2"),\n      subscriptionId: HASH("3"),\n      newFixedBudget: 700n,\n    });\n    expect(receipt.result?.transactions[0]).toMatchObject({\n      stage: "top-up",\n      txHash: HASH("2"),\n    });\n  });\n\n  it("retains completed transaction evidence from an exact partial-completion error", async () => {\n    const partial = Object.assign(new Error("Filecoin Boss operation failed at stage pause."), {\n      name: "BossServicesPartialCompletionError",\n      failedStage: "pause",\n      completed: [transaction("deposit", "6"), transaction("deploy-account", "7")],\n    });\n    const services = manager({\n      pause: vi.fn(async () => {\n        throw partial;\n      }),\n    });\n\n    const receipt = await executeBossLifecycleReview(services, review({ action: "pause" }), context());\n\n    expect(receipt.status).toBe("partial");\n    expect(receipt.result).toEqual({\n      failedStage: "pause",\n      transactions: [\n        {\n          stage: "deposit",\n          txHash: HASH("6"),\n          receiptStatus: "1",\n          blockNumber: "123",\n        },\n        {\n          stage: "deploy-account",\n          txHash: HASH("7"),\n          receiptStatus: "1",\n          blockNumber: "123",\n        },\n      ],\n    });\n    expect(receipt.error).toContain("failed at stage");\n    expect(services.reconcile).toHaveBeenCalledTimes(1);\n  });\n\n  it("reconciles exactly once after a thrown SDK failure", async () => {\n    const services = manager({\n      stop: vi.fn(async () => {\n        throw new Error("wallet rejected");\n      }),\n    });\n\n    const receipt = await executeBossLifecycleReview(services, review({ action: "stop" }), context());\n\n    expect(receipt).toMatchObject({\n      status: "failed",\n      error: "wallet rejected",\n      reconciliation: { status: "succeeded" },\n    });\n    expect(services.reconcile).toHaveBeenCalledTimes(1);\n  });\n\n  it("rejects a cloned review whose action changed after confirmation", async () => {\n    const services = manager();\n    const prepared = review();\n    const tampered = { ...prepared, action: "stop" } as BossLifecycleReview;\n\n    await expect(executeBossLifecycleReview(services, tampered, context())).rejects.toMatchObject({\n      code: "INVALID_REVIEW",\n    });\n    expect(services.sync).not.toHaveBeenCalled();\n    expect(services.stop).not.toHaveBeenCalled();\n    expect(services.reconcile).not.toHaveBeenCalled();\n  });\n\n  it("rejects a cloned top-up review whose fixed-budget target changed", async () => {\n    const services = manager();\n    const prepared = review({ action: "top-up", newFixedBudget: 500n });\n    const tampered = { ...prepared, newFixedBudget: 900n } as BossLifecycleReview;\n\n    await expect(executeBossLifecycleReview(services, tampered, context())).rejects.toMatchObject({\n      code: "INVALID_REVIEW",\n    });\n    expect(services.topUp).not.toHaveBeenCalled();\n    expect(services.reconcile).not.toHaveBeenCalled();\n  });\n\n  it("expires a review after five minutes before any SDK call", async () => {\n    const services = manager();\n    const prepared = review();\n\n    await expect(\n      executeBossLifecycleReview(\n        services,\n        prepared,\n        context({ nowMs: CREATED_AT + BOSS_LIFECYCLE_REVIEW_MAX_AGE_MS + 1 }),\n      ),\n    ).rejects.toMatchObject({\n      code: "STALE_REVIEW",\n    });\n    expect(services.sync).not.toHaveBeenCalled();\n    expect(services.reconcile).not.toHaveBeenCalled();\n  });\n\n  it("rejects changed live context before any SDK call", async () => {\n    const services = manager();\n\n    await expect(\n      executeBossLifecycleReview(services, review(), context({ wallet: ADDRESS("f") })),\n    ).rejects.toBeInstanceOf(BossLifecycleError);\n    expect(services.sync).not.toHaveBeenCalled();\n    expect(services.reconcile).not.toHaveBeenCalled();\n  });\n\n  it("serializes bigint evidence without precision loss", () => {\n    expect(serializeBossLifecycleEvidence({ amount: 9007199254740993123456789n })).toContain(\n      \'"9007199254740993123456789"\',\n    );\n  });\n\n  it("resolves only a complete maintained Synapse.services manager", () => {\n    expect(resolveBossServicesManager({ services: manager() }).status).toBe("available");\n    expect(resolveBossServicesManager({ services: { sync: () => undefined } })).toMatchObject({\n      status: "unavailable",\n      reason: expect.stringContaining("missing required"),\n    });\n    expect(resolveBossServicesManager(null)).toMatchObject({\n      status: "unavailable",\n    });\n  });\n});\n', 'apps/explorer/src/components/BossLifecycleConsole/index.tsx': '"use client";\n\nimport { Button } from "@filecoin-foundation/ui-filecoin/Button";\nimport type { Subscription } from "@filecoin-pay/types/boss";\nimport { useMemo, useState } from "react";\nimport { useAccount } from "wagmi";\nimport { getChain } from "@/constants/chains";\nimport useSynapse from "@/hooks/useSynapse";\nimport {\n  BOSS_LIFECYCLE_REVIEW_MAX_AGE_MS,\n  type BossLifecycleAction,\n  type BossLifecycleCurrentContext,\n  type BossLifecycleExecutionReceipt,\n  type BossLifecycleReview,\n  compareBossLifecycleReview,\n  executeBossLifecycleReview,\n  prepareBossLifecycleReview,\n  resolveBossServicesManager,\n  SYNAPSE_BOSS_SERVICES_PROVENANCE,\n  serializeBossLifecycleEvidence,\n} from "@/services/boss/lifecycle";\nimport type { Network } from "@/types";\n\nconst POSITIVE_DECIMAL = /^[1-9]\\d*$/;\n\ninterface BossLifecycleConsoleProps {\n  network: Network;\n  subscription: Subscription;\n  onRefresh: () => void;\n}\n\ninterface LifecycleActionDefinition {\n  action: BossLifecycleAction;\n  label: string;\n  description: string;\n  available: boolean;\n  unavailableReason?: string;\n}\n\nexport default function BossLifecycleConsole({ network, subscription, onRefresh }: BossLifecycleConsoleProps) {\n  const { address, chainId, isConnected } = useAccount();\n  const { synapse } = useSynapse();\n  const services = useMemo(() => resolveBossServicesManager(synapse), [synapse]);\n  const targetChainId = getChain(network).id;\n  const [newFixedBudget, setNewFixedBudget] = useState("");\n  const [review, setReview] = useState<BossLifecycleReview | null>(null);\n  const [receipt, setReceipt] = useState<BossLifecycleExecutionReceipt | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [isExecuting, setIsExecuting] = useState(false);\n\n  const currentContext: BossLifecycleCurrentContext = {\n    chainId,\n    wallet: address,\n    account: subscription.accountAddress,\n    subscriptionId: subscription.subscriptionId,\n    railId: subscription.railId,\n  };\n  const reviewMismatches = review ? compareBossLifecycleReview(review, currentContext) : [];\n  const walletReady = isConnected && address !== undefined && chainId === targetChainId;\n  const sdkReady = services.status === "available";\n  const canPrepare = walletReady && sdkReady && !isExecuting;\n  const reviewLifetimeMinutes = BOSS_LIFECYCLE_REVIEW_MAX_AGE_MS / 60_000;\n\n  const actions: LifecycleActionDefinition[] = [\n    {\n      action: "sync",\n      label: "Review capacity sync",\n      description: "Prepare one permissionless capacity-resource synchronization call.",\n      available:\n        subscription.billingKind === 1 &&\n        ["PENDING_ACTIVATION", "ACTIVE", "PAUSED"].includes(subscription.state),\n      unavailableReason: "Capacity sync is available only for live stream-capacity subscriptions.",\n    },\n    {\n      action: "top-up",\n      label: "Review fixed-budget target",\n      description:\n        "Prepare one explicit absolute fixed-budget target in token base units. This is not an additive amount.",\n      available: subscription.billingKind === 2 && !["TERMINATING", "ENDED"].includes(subscription.state),\n      unavailableReason: "Fixed-budget top-up is available only for non-terminal metered subscriptions.",\n    },\n    {\n      action: "pause",\n      label: "Review pause",\n      description: "Prepare one pause request. The SDK and contract enforce signer authority.",\n      available: subscription.state === "ACTIVE" && subscription.pauseAllowed,\n      unavailableReason: subscription.pauseAllowed\n        ? "Pause requires an active subscription."\n        : "The accepted subscription terms do not allow pause.",\n    },\n    {\n      action: "resume",\n      label: "Review resume",\n      description: "Prepare one resume request from the currently paused service.",\n      available: subscription.state === "PAUSED",\n      unavailableReason: "Resume requires a paused subscription.",\n    },\n    {\n      action: "stop",\n      label: "Review stop",\n      description:\n        "Prepare one Boss-operator stop. This terminates only the add-on and must preserve the base FWSS rail.",\n      available: ["PENDING_ACTIVATION", "ACTIVE", "PAUSED", "EXHAUSTED"].includes(subscription.state),\n      unavailableReason: "Stop is unavailable after termination has begun or completed.",\n    },\n  ];\n\n  const prepare = (action: BossLifecycleAction) => {\n    setError(null);\n    setReceipt(null);\n    try {\n      if (!address || chainId === undefined) {\n        throw new Error("Connect a wallet before preparing an action");\n      }\n      const fixedBudget =\n        action === "top-up"\n          ? POSITIVE_DECIMAL.test(newFixedBudget)\n            ? BigInt(newFixedBudget)\n            : (() => {\n                throw new Error(\n                  "New fixed budget must be a positive canonical decimal integer in token base units",\n                );\n              })()\n          : undefined;\n\n      setReview(\n        prepareBossLifecycleReview({\n          action,\n          chainId,\n          wallet: address,\n          account: subscription.accountAddress,\n          subscriptionId: subscription.subscriptionId,\n          railId: subscription.railId,\n          newFixedBudget: fixedBudget,\n          createdAtMs: Date.now(),\n        }),\n      );\n    } catch (cause) {\n      setReview(null);\n      setError(errorMessage(cause));\n    }\n  };\n\n  const execute = async () => {\n    if (!review || services.status !== "available") return;\n\n    setError(null);\n    setIsExecuting(true);\n    try {\n      const nextReceipt = await executeBossLifecycleReview(services.manager, review, {\n        ...currentContext,\n        nowMs: Date.now(),\n      });\n      setReceipt(nextReceipt);\n      setReview(null);\n      onRefresh();\n    } catch (cause) {\n      setError(errorMessage(cause));\n    } finally {\n      setIsExecuting(false);\n    }\n  };\n\n  return (\n    <section className=\'rounded-xl border bg-background p-5 shadow-sm\' aria-labelledby=\'boss-lifecycle-console-title\'>\n      <div>\n        <p className=\'text-xs font-semibold uppercase tracking-wide text-muted-foreground\'>Wallet console</p>\n        <h2 id=\'boss-lifecycle-console-title\' className=\'mt-1 text-lg font-semibold\'>\n          Manage existing Boss service\n        </h2>\n        <p className=\'mt-1 text-sm text-muted-foreground\'>\n          Every button creates a normalized, frozen review first. Confirmation executes exactly one maintained Synapse\n          SDK call, retains its transaction evidence, and reconciles Boss, Pay, and resource state once afterward.\n          Reviews expire after {reviewLifetimeMinutes} minutes.\n        </p>\n      </div>\n\n      <div className=\'mt-4 rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-100\'>\n        <p className=\'font-semibold\'>New-service attach remains fail-closed</p>\n        <p className=\'mt-1\'>\n          Safe attach requires the complete provider-signed offer, acceptance calldata, pricing/resource payloads, and\n          signer evidence. The read index does not reconstruct that executable payload, so no raw JSON or bespoke\n          contract-call fallback is provided.\n        </p>\n      </div>\n\n      {services.status === "unavailable" && (\n        <div\n          className=\'mt-4 rounded-lg border border-slate-300 bg-slate-50 p-4 text-sm text-slate-950 dark:border-slate-700 dark:bg-slate-950/30 dark:text-slate-100\'\n          role=\'status\'\n        >\n          <p className=\'font-semibold\'>Synapse Boss release gate</p>\n          <p className=\'mt-1\'>{services.reason}</p>\n          <p className=\'mt-2 break-all text-xs\'>\n            Required tracker authority: {SYNAPSE_BOSS_SERVICES_PROVENANCE.repository}@\n            {SYNAPSE_BOSS_SERVICES_PROVENANCE.commit}\n          </p>\n        </div>\n      )}\n\n      {!isConnected && (\n        <p className=\'mt-4 rounded-lg border bg-muted/40 p-4 text-sm text-muted-foreground\'>\n          Connect a wallet to prepare an action. No read-only service data requires a signer.\n        </p>\n      )}\n\n      {isConnected && chainId !== targetChainId && (\n        <p\n          className=\'mt-4 rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-100\'\n          role=\'alert\'\n        >\n          Wallet chain {chainId ?? "unknown"} does not match route chain {targetChainId}. Switch networks before review.\n        </p>\n      )}\n\n      <div className=\'mt-5 grid gap-4 lg:grid-cols-2\'>\n        {actions.map((definition) => (\n          <div key={definition.action} className=\'rounded-lg border p-4\'>\n            <p className=\'font-semibold\'>{definition.label}</p>\n            <p className=\'mt-1 text-sm text-muted-foreground\'>{definition.description}</p>\n            {definition.action === "top-up" && (\n              <label className=\'mt-3 block text-sm font-medium\'>\n                New fixed budget in token base units (absolute target)\n                <input\n                  className=\'mt-1 w-full rounded-md border bg-background px-3 py-2 font-mono text-sm\'\n                  inputMode=\'numeric\'\n                  value={newFixedBudget}\n                  onChange={(event) => setNewFixedBudget(event.target.value)}\n                  placeholder={subscription.currentFixedBudget}\n                  disabled={isExecuting}\n                />\n              </label>\n            )}\n            <Button\n              className=\'mt-3\'\n              onClick={() => prepare(definition.action)}\n              variant=\'tertiary\'\n              size=\'compact\'\n              disabled={!canPrepare || !definition.available}\n            >\n              {definition.label}\n            </Button>\n            {!definition.available && (\n              <p className=\'mt-2 text-xs text-muted-foreground\'>{definition.unavailableReason}</p>\n            )}\n          </div>\n        ))}\n      </div>\n\n      {review && (\n        <div className=\'mt-5 rounded-xl border border-blue-200 bg-blue-50 p-4 text-sm text-blue-950 dark:border-blue-900 dark:bg-blue-950/30 dark:text-blue-100\'>\n          <div className=\'flex flex-wrap items-start justify-between gap-3\'>\n            <div>\n              <p className=\'font-semibold\'>Review {review.action}</p>\n              <p className=\'mt-1\'>No transaction has been submitted. Any payload change invalidates this review.</p>\n            </div>\n            <code className=\'max-w-full break-all text-xs\'>{review.reviewKey}</code>\n          </div>\n          <dl className=\'mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3\'>\n            <ReviewField label=\'Wallet\' value={review.wallet} />\n            <ReviewField label=\'Chain ID\' value={review.chainId.toString()} />\n            <ReviewField label=\'Boss account\' value={review.account} />\n            <ReviewField label=\'Subscription ID\' value={review.subscriptionId} />\n            <ReviewField label=\'Rail ID\' value={review.railId} />\n            <ReviewField\n              label=\'New fixed budget\'\n              value={review.newFixedBudget?.toString() ?? "Not applicable"}\n            />\n          </dl>\n\n          {reviewMismatches.length > 0 && (\n            <div\n              className=\'mt-4 rounded-lg border border-red-200 bg-red-50 p-3 text-red-950 dark:border-red-900 dark:bg-red-950/30 dark:text-red-100\'\n              role=\'alert\'\n            >\n              <p className=\'font-semibold\'>Review invalidated</p>\n              <ul className=\'mt-2 list-disc space-y-1 pl-5 text-xs\'>\n                {reviewMismatches.map((mismatch) => (\n                  <li key={mismatch.field}>\n                    {mismatch.field}: reviewed <code>{mismatch.reviewed}</code>, current{" "}\n                    <code>{mismatch.current}</code>\n                  </li>\n                ))}\n              </ul>\n            </div>\n          )}\n\n          <div className=\'mt-4 flex flex-wrap gap-3\'>\n            <Button\n              onClick={() => void execute()}\n              variant=\'primary\'\n              size=\'compact\'\n              disabled={isExecuting || reviewMismatches.length > 0 || services.status !== "available"}\n            >\n              {isExecuting ? "Submitting one action…" : `Confirm ${review.action}`}\n            </Button>\n            <Button onClick={() => setReview(null)} variant=\'tertiary\' size=\'compact\' disabled={isExecuting}>\n              Cancel review\n            </Button>\n          </div>\n        </div>\n      )}\n\n      {error && (\n        <div\n          className=\'mt-5 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-950 dark:border-red-900 dark:bg-red-950/30 dark:text-red-100\'\n          role=\'alert\'\n        >\n          {error}\n        </div>\n      )}\n\n      {receipt && (\n        <div className=\'mt-5 rounded-xl border p-4\'>\n          <p className=\'font-semibold\'>Action receipt: {receipt.status}</p>\n          <p className=\'mt-1 text-sm text-muted-foreground\'>\n            A fresh review is required before any retry. The console never reruns a partial or rejected action\n            automatically.\n          </p>\n          {receipt.result?.failedStage && (\n            <p className=\'mt-2 text-sm\'>Failed SDK stage: {receipt.result.failedStage}</p>\n          )}\n          {receipt.result?.transactions && receipt.result.transactions.length > 0 && (\n            <ol className=\'mt-4 space-y-2\'>\n              {receipt.result.transactions.map((transaction, index) => (\n                <li key={`${transaction.stage}-${transaction.txHash}-${index}`} className=\'rounded-lg border p-3 text-sm\'>\n                  <p className=\'font-medium\'>{transaction.stage}</p>\n                  <code className=\'mt-1 block break-all text-xs\'>{transaction.txHash}</code>\n                  <p className=\'mt-1 text-xs text-muted-foreground\'>\n                    Receipt status {transaction.receiptStatus ?? "unavailable"}\n                    {transaction.blockNumber ? ` · block ${transaction.blockNumber}` : ""}\n                  </p>\n                </li>\n              ))}\n            </ol>\n          )}\n          <details className=\'mt-4\'>\n            <summary className=\'cursor-pointer text-sm font-semibold\'>Exact SDK and reconciliation evidence</summary>\n            <pre className=\'mt-2 max-h-96 overflow-auto rounded-lg bg-muted p-3 text-xs\'>\n              {serializeBossLifecycleEvidence(receipt)}\n            </pre>\n          </details>\n        </div>\n      )}\n    </section>\n  );\n}\n\nfunction ReviewField({ label, value }: { label: string; value: string }) {\n  return (\n    <div className=\'min-w-0\'>\n      <dt className=\'text-xs font-semibold uppercase tracking-wide opacity-70\'>{label}</dt>\n      <dd className=\'mt-1 break-all font-mono text-xs\'>{value}</dd>\n    </div>\n  );\n}\n\nfunction errorMessage(error: unknown): string {\n  if (error instanceof Error) {\n    const details = "details" in error && Array.isArray(error.details) ? error.details.join("; ") : "";\n    return details ? `${error.message}: ${details}` : error.message;\n  }\n  return String(error);\n}\n', 'packages/types/scripts/validate-synapse-boss-services.mjs': 'import { readFileSync } from "node:fs";\n\nconst [managerPath, typesPath, errorsPath] = process.argv.slice(2);\nif (!managerPath || !typesPath || !errorsPath) {\n  throw new Error(\n    "usage: validate-synapse-boss-services.mjs <manager.ts> <types.ts> <errors.ts>",\n  );\n}\n\nconst manager = normalize(readFileSync(managerPath, "utf8"));\nconst types = normalize(readFileSync(typesPath, "utf8"));\nconst errors = normalize(readFileSync(errorsPath, "utf8"));\n\nrequireText(manager, "async topUp(options: BossServicesTopUpOptions)", "manager exposes the typed top-up method");\nrequireText(manager, "topUpBossFixedBudgetCall(options)", "top-up forwards the typed options");\nrequireText(types, "newFixedBudget: bigint", "top-up uses the absolute newFixedBudget input");\nrequireText(types, "export interface BossServicesTransactionEvidence", "transaction evidence is exported");\nrequireText(types, "hash: Hex", "transaction evidence carries an exact hash");\nrequireText(types, "receipt: TransactionReceipt | null", "transaction evidence carries a receipt");\nrequireText(errors, "readonly completed: BossServicesTransactionEvidence[]", "partial errors retain completed evidence");\nrequireText(errors, "readonly failedStage: BossServicesStage", "partial errors retain the failed stage");\n\nfor (const method of ["sync", "topUp", "pause", "resume", "stop"]) {\n  requireText(manager, `async ${method}(`, `manager exposes ${method}`);\n}\n\nconsole.log("Explorer lifecycle adapter matches the pinned Synapse Boss services API.");\n\nfunction normalize(value) {\n  return value.replace(/\\s+/g, " ").trim();\n}\n\nfunction requireText(source, expected, description) {\n  if (!source.includes(expected)) {\n    throw new Error(`Pinned Synapse API drift: ${description}; missing ${JSON.stringify(expected)}`);\n  }\n}\n'}

for relative, content in FILES.items():
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.rstrip() + "\n")

