new_import = old_import + 'import BossLifecycleConsole from "@/components/BossLifecycleConsole";\n'
if text.count(old_import) != 1 or 'BossLifecycleConsole from' in text:
    raise SystemExit("BossService import surface no longer matches the qualified D0 source")
text = text.replace(old_import, new_import, 1)
old_insert = "          <BossPayAssociation network={network} railId={subscription.railId} subscription={subscription} />\n\n          <BossSectionCard"
new_insert = "          <BossPayAssociation network={network} railId={subscription.railId} subscription={subscription} />\n          <BossLifecycleConsole network={network} subscription={subscription} onRefresh={refresh} />\n\n          <BossSectionCard"
if text.count(old_insert) != 1:
    raise SystemExit("BossService lifecycle insertion point no longer matches the qualified D0 source")
